// UpsertMany inserts each input, or, when a row already holds its value of
// the unique key on, sets each field update names of that row to the value
// the input would have inserted, and returns each input's row and what it did
// with it, in the inputs' order (D89). Each insert writes the row with the
// fields its behaviors own as the core's create gives them (D103), and update
// names none of them: only their operations change them. It runs in a
// transaction of its own when none is open, the core's creates first, then a
// statement per batch of rows, opts.Batch or as many as Postgres binds the
// parameters of. An update that names no field leaves each row that holds a
// key as it is. Two inputs of one batch that hold one key fail the statement,
// and a key over an expression, whose rows the statement's cannot be matched
// to the inputs by, is refused.
func (r *OrderRepository) UpsertMany(ctx context.Context, inputs []*OrderCreate, on OrderUniqueKey, update OrderFields, opts *UpsertOptions) ([]UpsertResult[*types.Order], error) {
	key, ok := orderUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: Order has no unique key %q", string(on))
	}
	if key.rows == "" {
		return nil, upsertExpressionKey("UpsertMany", "Order", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if update.Id {
		return nil, fmt.Errorf("orm: UpsertMany of Order sets the fields an update sets, not id")
	}
	if update.Version {
		return nil, fmt.Errorf("orm: UpsertMany of Order sets the fields an update sets, not _version")
	}
	if update.Status {
		return nil, fmt.Errorf("orm: UpsertMany of Order sets the fields an update sets, not %q, which behavior Workflow on status owns (D103): only its operations change it", "status")
	}
	if update.StatusEnteredAt {
		return nil, fmt.Errorf("orm: UpsertMany of Order sets the fields an update sets, not %q, which behavior Workflow on status owns (D103): only its operations change it", "statusEnteredAt")
	}
	batch, err := upsertBatch("Order", opts.Batch, 13106)
	if err != nil {
		return nil, err
	}
	if len(inputs) == 0 {
		return []UpsertResult[*types.Order]{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]UpsertResult[*types.Order], error) {
		repo := &OrderRepository{tx: tx, txDB: r.database()}
		rows, err := repo.upsertInputs(ctx, inputs)
		if err != nil {
			return nil, err
		}
		return repo.upsertBatches(ctx, rows, on, update, batch, opts.OnlyIfChanged)
	})
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// only if changed, and the second statement of each encrypted field.
func (r *OrderRepository) upsertBatches(ctx context.Context, inputs []*types.Order, on OrderUniqueKey, update OrderFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Order], error) {
	key := orderUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Title {
		setClauses = append(setClauses, `title = EXCLUDED.title`)
		compareCurrent = append(compareCurrent, `"order".title`)
		compareNext = append(compareNext, `EXCLUDED.title`)
	}
	if update.PlacedAt {
		setClauses = append(setClauses, `placed_at = EXCLUDED.placed_at`)
		compareCurrent = append(compareCurrent, `"order".placed_at`)
		compareNext = append(compareNext, `EXCLUDED.placed_at`)
	}

	results := make([]UpsertResult[*types.Order], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := orderUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: title
			{
				cell := batchInsertCell{column: `title`, set: true}
				cell.value = input.Title
				row = append(row, cell)
			}
			// Optional field: placedAt
			{
				cell := batchInsertCell{column: `placed_at`}
				if input.PlacedAt != nil {
					cell.value = time.Time(*input.PlacedAt)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: status
			{
				cell := batchInsertCell{column: `status`, set: true}
				cell.value = input.Status
				row = append(row, cell)
			}
			// Optional field: statusEnteredAt
			{
				cell := batchInsertCell{column: `status_entered_at`}
				if input.StatusEnteredAt != nil {
					cell.value = time.Time(*input.StatusEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field leaves each row as it is.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO "order" (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "title", "placed_at", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = orderKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Order], len(prepared))
		for n, row := range returned {
			text, ok := orderKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Order wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Order]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, only if changed,
		// which it reads back by its key, or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged {
				return nil, fmt.Errorf("the Order row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Order, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Order row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Order]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *OrderRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Order, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Order
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert only if changed left as they were
// (D89). A key no live row holds is ErrNotFound.
func (r *OrderRepository) rowsOfKeys(ctx context.Context, on OrderUniqueKey, keys [][]any, inputs []*types.Order) ([]*types.Order, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(orderUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Order{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := orderKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Order, len(inputs))
	for i, input := range inputs {
		text, _ := orderKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Order row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// CreateMany inserts multiple Order rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *OrderRepository) CreateMany(ctx context.Context, inputs []*OrderCreate) ([]*types.Order, error) {
	if len(inputs) == 0 {
		return []*types.Order{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Order, error) {
		repo := &OrderRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Order, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Order row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *OrderRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *OrderUpdate) (*types.Order, error) {
	if update == nil {
		update = &OrderUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Order, error) {
		repo := &OrderRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Order", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return nil, behaviorNotFound(err, "Order", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Order records matching the filter
func (r *OrderRepository) UpdateMany(ctx context.Context, filter *OrderFilter, update *OrderUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Title != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`title = $%d`, paramNum))
		values = append(values, *update.Title)
	}
	if update.PlacedAt != nil && update.PlacedAtSetNull {
		return 0, fmt.Errorf("placed_at cannot be updated with both value and null assignment")
	}
	if update.PlacedAtSetNull {
		setClauses = append(setClauses, `placed_at = NULL`)
	} else if update.PlacedAt != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`placed_at = $%d`, paramNum))
		values = append(values, time.Time(*update.PlacedAt))
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE "order" SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Order row by ID through the
// behaviors' core (D103), in a transaction. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *OrderRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Order", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Order", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Order records matching the filter
func (r *OrderRepository) DeleteMany(ctx context.Context, filter *OrderFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM "order"%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
